package com.bank.signaturemanagement.service;
import com.bank.signaturemanagement.entity.SignatureBook; import com.bank.signaturemanagement.repository.SignatureBookRepository; import org.springframework.security.access.AccessDeniedException; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class SignatureBookPublicationService {private final SignatureBookRepository books;private final AccessControlService access;private final AuditService audit;public SignatureBookPublicationService(SignatureBookRepository b,AccessControlService a,AuditService audit){books=b;access=a;this.audit=audit;}@Transactional public void publish(SignatureBook current,String username){if(!access.hasAnyRole(username,"PD","ADMIN"))throw new AccessDeniedException("Only PD may publish a signature book");books.archiveOthers(current.getId());current.setStatus("CURRENT");audit.record(username,"BOOK_PUBLISH","SIGNATURE_BOOK",String.valueOf(current.getId()),null,"SUCCESS",null,"CURRENT",null);}}
